/**
 * @method
 * @name ins_Search
 * @description ins Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_Search = async function() {
    // 데이터셋 초기화
    scwin.initDs("ins_Search");

    // 조회조건 체크.
    if (!await scwin.chkValid("ins_Search")) {
        return;
    }

    // Lodaing~~~ 표시

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    const sbmOptions = {
        id : "sbm_dts_ApplInfo",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ApplInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

