/**
 * @method
 * @name setCombo
 * @description 콤보박스 만들기
 * @returns {void}
 * @hidden N
 */
scwin.setCombo = function() {
    ins_combo_set(dts_CurrTpCd, "ULDINS15800.xml", SCREN_PROCS_TP_CD_01, "02475"); // 발행통화
    ins_combo_set(dts_DomFornIsuTpCd, "ULDINS15800.xml", SCREN_PROCS_TP_CD_01, "03407"); // 발행통화

};

/**
 * @method
